


export type MerchantAccountSessionStripeComponentInput = { /** Collection instructions for a policy-aware component. Omitted for other components. Map future_requirements to futureRequirements when calling setCollectionOptions. */ "collection_options"?: { /** Requirement collection breadth to pass as fields to setCollectionOptions. */ "fields": "currently_due" | "eventually_due"; /** Whether to collect future requirements. Pass this value as futureRequirements to setCollectionOptions. */ "future_requirements": "omit" | "include"; /** Targeted requirement collection restriction to pass as requirements to setCollectionOptions. Omitted when collection is not targeted. */ "requirements"?: { /** Stripe requirement paths to collect exclusively when effective_policy.targeting is targeted. They come from the targeted_requirement_ids you sent or from Flint's remediation recommendation. */ "only": Array<string>; }; }; /** Stripe component name authorized by this session. tax_documents uses the Stripe name documents. Convert underscores to hyphens when calling Connect.create. */ "component": "account_onboarding" | "account_management" | "payouts" | "balances" | "documents" | "notification_banner"; };
